import type { CSSProperties, ReactNode } from "react";
import { clamp } from "../../parts/time";
import { ACCENT, PRIMARY } from "./world";

/**
 * The simulation for "Simulate this circuit, with sliders for L, C and R", laid out like the app's own sim template
 * (the English layout of mathbooklm/bench/results/sim-20261108T205709Z/rc-charging, a sim the app's prompt and runtime
 * made): the stage (circuit, live plot) with the "Answers" cards beside it, the play bar, then the sliders with their
 * typeable value fields and "Question values". It is built here, not generated by the app, but its physics is exact:
 * a series RLC loop with the capacitor charged to V₀ and no current at t = 0, solved in closed form (under-, critically
 * and over-damped). Like the app's runtime, the run restarts from t = 0 when a value changes.
 */
export const SIM_W = 560;
export const SIM_H = 350;
export const WINDOW = 0.02; // the plot's 20 ms
export const TITLE = "LC circuit: energy sloshing between C and L";

const TEAL = "#0ca678";
const ORANGE = "#f08c00";
const font = '"Arimo", Arial, sans-serif';

export type SimState = { L: number; C: number; R: number; V0: number; t: number; hot?: Knob; field?: string; changed?: boolean };
export const QUESTION: Omit<SimState, "t"> = { L: 0.01, C: 100e-6, R: 0, V0: 9 };

/** Charge on C and the current, at time t, for a series RLC loop released from q = CV₀, I = 0. */
export function response({ L, C, R, V0 }: SimState, t: number) {
  const Q0 = C * V0;
  const w0 = 1 / Math.sqrt(L * C);
  const a = R / (2 * L);
  const e = Math.exp(-a * t);
  const d = w0 * w0 - a * a;
  if (Math.abs(d) < 1e-6 * w0 * w0) return { q: Q0 * e * (1 + a * t), I: Q0 * a * a * t * e };
  if (d > 0) {
    const wd = Math.sqrt(d);
    return { q: Q0 * e * (Math.cos(wd * t) + (a / wd) * Math.sin(wd * t)), I: Q0 * e * ((w0 * w0) / wd) * Math.sin(wd * t) };
  }
  const b = Math.sqrt(-d);
  return { q: Q0 * e * (Math.cosh(b * t) + (a / b) * Math.sinh(b * t)), I: Q0 * e * ((w0 * w0) / b) * Math.sinh(b * t) };
}

export const answers = (s: SimState) => {
  const w0 = 1 / Math.sqrt(s.L * s.C);
  return { w0, f: w0 / (2 * Math.PI), Imax: s.V0 * Math.sqrt(s.C / s.L), Rc: 2 * Math.sqrt(s.L / s.C) };
};

// ── controls ─────────────────────────────────────────────────────────────────

export const KNOBS = {
  L: { label: "Inductance L", y: 244, range: [1, 40], unit: "mH", get: (s: SimState) => s.L * 1000, fmt: (v: number) => v.toFixed(0) },
  C: { label: "Capacitance C", y: 270, range: [10, 500], unit: "μF", get: (s: SimState) => s.C * 1e6, fmt: (v: number) => v.toFixed(0) },
  R: { label: "Resistance R", y: 296, range: [0, 30], unit: "Ω", get: (s: SimState) => s.R, fmt: (v: number) => v.toFixed(1) },
  V0: { label: "Charged to V₀", y: 322, range: [1, 20], unit: "V", get: (s: SimState) => s.V0, fmt: (v: number) => v.toFixed(1) },
} as const;
export type Knob = keyof typeof KNOBS;
const SL = { x: 118, w: 170 };
const FIELD = { x: 298, w: 54 };
const frac = (k: Knob, v: number) => clamp((v - KNOBS[k].range[0]) / (KNOBS[k].range[1] - KNOBS[k].range[0]));
/** A slider's thumb, in sim pixels. */
export const thumbAt = (k: Knob, v: number) => ({ x: SL.x + SL.w * frac(k, v), y: KNOBS[k].y });
/** A value field's middle, in sim pixels. */
export const fieldAt = (k: Knob) => ({ x: FIELD.x + FIELD.w / 2, y: KNOBS[k].y });
export const QUESTION_BTN = { x: 430, y: 309, w: 112, h: 26 };
/** The value a knob shows in the state. */
export const knobValue = (s: SimState, k: Knob) => KNOBS[k].get(s);

function Slider({ x, y, w, k, hot }: { x: number; y: number; w: number; k: number; hot?: boolean }) {
  return (
    <div style={{ position: "absolute", left: x, top: y - 2, width: w, height: 4, borderRadius: 2, background: "#dcdaf6" }}>
      <div style={{ width: `${k * 100}%`, height: "100%", borderRadius: 2, background: ACCENT }} />
      <div style={{ position: "absolute", left: `calc(${k * 100}% - 7px)`, top: -5, width: 14, height: 14, borderRadius: "50%", background: ACCENT, boxShadow: hot ? `0 0 0 5px rgba(105,101,219,.22)` : undefined }} />
    </div>
  );
}

function Row({ s, k }: { s: SimState; k: Knob }) {
  const K = KNOBS[k];
  const v = K.get(s);
  const t: CSSProperties = { position: "absolute", top: K.y - 8, fontSize: 11, color: "#444", whiteSpace: "nowrap" };
  const editing = s.field !== undefined && s.hot === k;
  return (
    <>
      <span style={{ ...t, left: 12 }}>{K.label}</span>
      <Slider x={SL.x} y={K.y} w={SL.w} k={frac(k, v)} hot={s.hot === k && !editing} />
      <span style={{ position: "absolute", left: FIELD.x, top: K.y - 10, width: FIELD.w, height: 20, boxSizing: "border-box", border: `1px solid ${editing ? ACCENT : "#d6d6dc"}`, boxShadow: editing ? "0 0 0 2px rgba(105,101,219,.2)" : undefined, borderRadius: 4, fontSize: 11, color: "#222", display: "flex", alignItems: "center", justifyContent: "flex-end", padding: "0 5px", background: "#fff" }}>
        {editing ? (
          <>
            <span>{s.field}</span>
            <span style={{ width: 1, height: 12, background: "#222", marginLeft: 1 }} />
          </>
        ) : (
          K.fmt(v)
        )}
      </span>
      <span style={{ ...t, left: FIELD.x + FIELD.w + 7 }}>{K.unit}</span>
    </>
  );
}

function Card({ y, label, value }: { y: number; label: string; value: string }) {
  return (
    <div style={{ position: "absolute", left: 384, top: y, width: 166, height: 40, padding: "4px 9px", borderRadius: 7, background: "#efeefc", boxSizing: "border-box" }}>
      <div style={{ fontSize: 9, color: "#666", whiteSpace: "nowrap" }}>{label}</div>
      <div style={{ fontSize: 16, fontWeight: 700, color: PRIMARY, marginTop: 1, whiteSpace: "nowrap" }}>{value}</div>
    </div>
  );
}

// ── the stage ────────────────────────────────────────────────────────────────

/** The circuit: C on the left, the coil on the right, R on top, with charge moving round it. */
function Circuit({ s, q, Q0 }: { s: SimState; q: number; Q0: number }) {
  const x0 = 28, x1 = 132, y0 = 34, y1 = 168;
  const per = 2 * (x1 - x0 + y1 - y0);
  // Charge that has left the top plate, as distance travelled round the loop.
  const moved = ((Q0 - q) / Q0) * 34;
  const along = (u: number) => {
    let d = ((u % per) + per) % per;
    const top = x1 - x0, right = y1 - y0;
    if (d < top) return [x0 + d, y0];
    d -= top;
    if (d < right) return [x1, y0 + d];
    d -= right;
    if (d < top) return [x1 - d, y1];
    d -= top;
    return [x0, y1 - d];
  };
  const dots = Array.from({ length: 14 }, (_, i) => along((i / 14) * per + moved));
  const plate = clamp(Math.abs(q) / Q0);
  const topPos = q >= 0;
  const cy = (y0 + y1) / 2;
  const coil = Array.from({ length: 4 }, (_, i) => `a8 8 0 0 1 0 16`).join(" ");
  return (
    <svg width={160} height={196} style={{ position: "absolute", left: 0, top: 0 }} fill="none" strokeLinecap="round" strokeLinejoin="round">
      {/* wires, with gaps for the parts */}
      <path d={`M${x0} ${cy - 6}V${y0}H62M98 ${y0}H${x1}V${cy - 32}M${x1} ${cy + 32}V${y1}H${x0}V${cy + 6}`} stroke="#495057" strokeWidth={1.6} />
      {/* C */}
      <path d={`M${x0 - 14} ${cy - 6}H${x0 + 14}M${x0 - 14} ${cy + 6}H${x0 + 14}`} stroke="#222" strokeWidth={2.4} />
      <text x={x0 - 26} y={cy + 4} fontSize={11} fill="#222" fontFamily={font}>C</text>
      <text x={x0 - 24} y={cy - 12} fontSize={11} fontWeight={700} fill="#e03131" opacity={0.25 + 0.75 * plate}>{topPos ? "+" : "−"}</text>
      <text x={x0 - 24} y={cy + 22} fontSize={11} fontWeight={700} fill="#1971c2" opacity={0.25 + 0.75 * plate}>{topPos ? "−" : "+"}</text>
      {/* R */}
      <path d={`M62 ${y0}l3 -6l6 12l6 -12l6 12l6 -12l6 12l3 -6`} stroke="#222" strokeWidth={1.6} />
      <text x={74} y={y0 - 12} fontSize={11} fill="#222" fontFamily={font}>R</text>
      {/* L */}
      <path d={`M${x1} ${cy - 32}${coil}`} stroke="#222" strokeWidth={1.8} />
      <text x={x1 + 14} y={cy + 4} fontSize={11} fill="#222" fontFamily={font}>L</text>
      {dots.map(([x, y], i) => (
        <circle key={i} cx={x} cy={y} r={2.6} fill={ACCENT} opacity={0.85} />
      ))}
      <text x={x0} y={190} fontSize={9.5} fill="#868e96" fontFamily={font}>{`q = ${(q * 1e6).toFixed(0)} μC`}</text>
    </svg>
  );
}

/** The live plot: V_C (dark) and I (teal) over the 20 ms window, drawn up to the sim's time. */
function Plot({ s }: { s: SimState }) {
  const X0 = 176, X1 = 352, Y0 = 22, Y1 = 166;
  const ym = (Y0 + Y1) / 2;
  const vk = (Y1 - Y0) / 2 / 10; // ±10 V
  const ik = (Y1 - Y0) / 2 / 2; // ±2 A
  const tt = clamp(s.t, 0, WINDOW);
  const steps = 240;
  let v = "";
  let i = "";
  const n = Math.max(1, Math.round((tt / WINDOW) * steps));
  for (let j = 0; j <= n; j++) {
    const t = (tt * j) / n;
    const r = response(s, t);
    const x = (X0 + ((X1 - X0) * t) / WINDOW).toFixed(1);
    v += `${j ? "L" : "M"}${x} ${(ym - (r.q / s.C) * vk).toFixed(1)}`;
    i += `${j ? "L" : "M"}${x} ${(ym - r.I * ik).toFixed(1)}`;
  }
  const now = response(s, tt);
  const nx = X0 + ((X1 - X0) * tt) / WINDOW;
  const ticks = [0, 5, 10, 15, 20];
  return (
    <svg width={SIM_W} height={196} style={{ position: "absolute", left: 0, top: 0 }} fill="none" fontFamily={font}>
      <path d={`M${X0} ${Y0}V${Y1}M${X1} ${Y0}V${Y1}`} stroke="#adb5bd" strokeWidth={1} />
      <path d={`M${X0} ${ym}H${X1}`} stroke="#ced4da" strokeWidth={1} />
      {ticks.map((t) => (
        <g key={t}>
          <path d={`M${X0 + ((X1 - X0) * t) / 20} ${Y1}v3`} stroke="#adb5bd" />
          <text x={X0 + ((X1 - X0) * t) / 20} y={Y1 + 13} fontSize={8.5} fill="#666" textAnchor="middle">{t}</text>
        </g>
      ))}
      {[-10, 0, 10].map((y) => (
        <text key={y} x={X0 - 4} y={ym - y * vk + 3} fontSize={8.5} fill="#333" textAnchor="end">{y}</text>
      ))}
      {[-2, 0, 2].map((y) => (
        <text key={y} x={X1 + 4} y={ym - y * ik + 3} fontSize={8.5} fill={TEAL}>{y}</text>
      ))}
      <text x={X0 - 4} y={12} fontSize={9.5} fill="#333" textAnchor="middle">V_C (V)</text>
      <text x={X1 + 4} y={12} fontSize={9.5} fill={TEAL} textAnchor="middle">I (A)</text>
      <text x={(X0 + X1) / 2} y={Y1 + 26} fontSize={9.5} fill="#333" textAnchor="middle">t (ms)</text>
      <path d={v} stroke="#212529" strokeWidth={1.8} />
      <path d={i} stroke={TEAL} strokeWidth={1.8} />
      <path d={`M${nx} ${Y0}V${Y1}`} stroke={ACCENT} strokeWidth={1} />
      <circle cx={nx} cy={ym - (now.q / s.C) * vk} r={3.4} fill={ORANGE} />
    </svg>
  );
}

/** The sim's page at 560×350. */
export function LcPage({ s }: { s: SimState }) {
  const A = answers(s);
  const Q0 = s.C * s.V0;
  const now = response(s, clamp(s.t, 0, WINDOW));
  const tt = clamp(s.t, 0, WINDOW);
  return (
    <div dir="ltr" style={{ position: "relative", width: SIM_W, height: SIM_H, fontFamily: font, color: "#222", overflow: "hidden" }}>
      <Circuit s={s} q={now.q} Q0={Q0} />
      <Plot s={s} />
      <div style={{ position: "absolute", left: 384, top: 2, fontSize: 10, color: "#666" }}>Answers</div>
      <Card y={17} label="ω₀ = 1/√(LC)" value={`${A.w0.toFixed(0)} rad/s`} />
      <Card y={61} label="f = ω₀ / 2π" value={`${A.f.toFixed(1)} Hz`} />
      <Card y={105} label="I_max = V₀ √(C/L)" value={`${A.Imax.toFixed(3)} A`} />
      <Card y={149} label="Critical R = 2 √(L/C)" value={`${A.Rc.toFixed(1)} Ω`} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 200, height: 1, background: "#ececf1" }} />
      {/* the play bar */}
      <span style={{ position: "absolute", left: 10, top: 206, width: 26, height: 22, borderRadius: 5, border: "1px solid #ddd", display: "grid", placeItems: "center", fontSize: 9, background: "#fff" }}>❚❚</span>
      <span style={{ position: "absolute", left: 40, top: 206, width: 26, height: 22, borderRadius: 5, border: "1px solid #ddd", display: "grid", placeItems: "center", fontSize: 12, color: "#444", background: "#fff" }}>↺</span>
      <span style={{ position: "absolute", left: 76, top: 217, width: 290 }}>
        <Slider x={0} y={0} w={290} k={tt / WINDOW} />
      </span>
      <span style={{ position: "absolute", left: 376, top: 211, fontSize: 10.5, color: "#555" }}>{(tt * 1000).toFixed(1)} ms / 20.0 ms</span>
      <span style={{ position: "absolute", left: 480, top: 206, width: 70, height: 22, border: "1px solid #ccc", borderRadius: 4, fontSize: 10, display: "flex", alignItems: "center", justifyContent: "space-around", boxSizing: "border-box", background: "#fff" }}>
        <span>0.005×</span>
        <span>▾</span>
      </span>
      {(Object.keys(KNOBS) as Knob[]).map((k) => (
        <Row key={k} s={s} k={k} />
      ))}
      <div style={{ position: "absolute", left: QUESTION_BTN.x, top: QUESTION_BTN.y, width: QUESTION_BTN.w, height: QUESTION_BTN.h, borderRadius: 6, border: "1px solid #e0e0e0", fontSize: 10.5, color: s.changed ? "#333" : "#bbb", display: "grid", placeItems: "center", boxSizing: "border-box", background: "#fff" }}>Question values</div>
    </div>
  );
}

export const SIM_CARD_HEADER = 30;

/** The chat's sim card: the app's header (title, versions, Code, Expand, Add to canvas), then the running sim. */
export function SimCard({ width, s, addHot }: { width: number; s: SimState; addHot?: boolean }) {
  const k = (width - 2) / SIM_W;
  return (
    <div dir="ltr" style={{ width, borderRadius: 10, background: "#f7f7f9", border: "1px solid #e5e7eb", overflow: "hidden", fontFamily: font }}>
      <div style={{ height: SIM_CARD_HEADER, display: "flex", alignItems: "center", gap: 8, padding: "0 10px", fontSize: 11.5, color: "#333" }}>
        <span style={{ flex: 1, fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{TITLE}</span>
        <span style={{ color: "#888", fontSize: 10.5 }}>v1</span>
        <span style={{ color: "#888" }}>{"</>"}</span>
        <span style={{ color: "#888" }}>⤢</span>
        <span style={{ color: addHot ? ACCENT : "#666", border: `1px solid ${addHot ? "#c7c5f2" : "#e5e7eb"}`, borderRadius: 6, padding: "1px 7px", background: addHot ? "#eeedfc" : "#fff", whiteSpace: "nowrap" }}>Add to canvas</span>
      </div>
      <div style={{ width: SIM_W, height: SIM_H, transform: `scale(${k})`, transformOrigin: "0 0", marginBottom: SIM_H * (k - 1) }}>
        <LcPage s={s} />
      </div>
    </div>
  );
}

/** The sim as a live element on the canvas: transparent, so the grid shows through, with the accent outline while active. */
export function SimBox({ s, active, children }: { s: SimState; active: boolean; children?: ReactNode }) {
  return (
    <div style={{ position: "relative", width: SIM_W, height: SIM_H, outline: active ? `1.5px solid ${ACCENT}` : "1px solid rgba(105,101,219,.18)", outlineOffset: 3 }}>
      <LcPage s={s} />
      {children}
    </div>
  );
}
